/** C ref: mhitu.c:2355 — @param {CPtr<struct monst>} mtmp @param {CInt} tmp @returns {CInt} */
function assess_dmg(mtmp, tmp) {
    if ((cptr.stI32o(mtmp, $monst_mhp, (cptr.ldI32o(mtmp, $monst_mhp) - tmp) | 0)) <= 0) {
        pline_mon(mtmp, __s_s_dies, Monnam(mtmp));
        xkilled(mtmp, NHM.XKILL_NOMSG);
        if (!(cptr.ldI32o((mtmp), $monst_mhp) < 1))
            return NHM.M_ATTK_HIT;
        return NHM.M_ATTK_AGR_DIED;
    }
    return NHM.M_ATTK_HIT;
}

/* can be used as ranged_attk_assessed() callback.
   Returns TRUE if monster is avoiding use of this attack */
/** C ref: mhitu.c:2393 — @param {CPtr<struct monst>} mtmp @param {CInt} attkidx @returns {CInt} */
export function mon_avoiding_this_attack(mtmp, attkidx) {
    let ptr = cptr.ldPtro(mtmp, $monst_data);
    let typ = -1;

    if (attkidx >= 0 &&
            (typ = get_atkdam_type(cptr.ld1uo2(
                ptr,
                attkidx,
                $sizeof_attack,
                $permonst_mattk + $attack_adtyp
            ))) >= 0 &&
            (cptr.ldU64o((mtmp), $monst_seen_resistance) & (cvt_adtyp_to_mseenres(uchar(typ)))))
        return 1;
    return 0;
}

/*
 * This would be equivalent to:
 *     ranged_attk_assessed(mtmp, mon_avoiding_this_attack)
 * but without the added assessment function call overhead.
 */
/** C ref: mhitu.c:2413 — @param {CPtr<struct monst>} mtmp @returns {CInt} */
export function ranged_attk_available(mtmp) {
    let i;
    let typ = -1;
    let ptr = cptr.ldPtro(mtmp, $monst_data);

    for (i = 0; i < NHM.NATTK; i++) {
        if (DISTANCE_ATTK_TYPE(cptr.ld1uo2(ptr, i, $sizeof_attack, $permonst_mattk)) &&
                (typ = get_atkdam_type(cptr.ld1uo2(
                    ptr,
                    i,
                    $sizeof_attack,
                    $permonst_mattk + $attack_adtyp
                ))) >= 0 &&
                (cptr.ldU64o((mtmp), $monst_seen_resistance) &
                    (cvt_adtyp_to_mseenres(uchar(typ)))) == 0n)
            return 1;
    }
    return 0;
}

/* FIXME:
 *  sequencing issue:  a monster's attack might cause poly'd hero
 *  to revert to normal form.  The messages for passive counterattack
 *  would look better if they came before reverting form, but we need
 *  to know whether hero reverted in order to decide whether passive
 *  damage applies.
 */
/**
 * C ref: mhitu.c:2435
 * @param {CPtr<struct permonst>} olduasmon
 * @param {CPtr<struct monst>} mtmp
 * @param {CPtr<struct attack>} mattk
 * @returns {CInt}
 */
function passiveum(olduasmon, mtmp, mattk) {
    let i;
    let tmp;
    let oldu_mattk = null;

    /*
     * mattk      == mtmp's attack that hit you;
     * oldu_mattk == your passive counterattack (even if mtmp's attack
     *               has already caused you to revert to normal form).
     */
    for (i = 0; !oldu_mattk; i++) {
        if (i >= NHM.NATTK)
            return NHM.M_ATTK_HIT;
        if (cptr.ld1uo2(olduasmon, i, $sizeof_attack, $permonst_mattk) == NHM.AT_NONE ||
                cptr.ld1uo2(olduasmon, i, $sizeof_attack, $permonst_mattk) == NHM.AT_BOOM)
            oldu_mattk = cptr.add(cptr.add(olduasmon, $permonst_mattk), i, $sizeof_attack);
    }
    if (cptr.ld1uo(oldu_mattk, $attack_damn))
        tmp = d((cptr.ld1uo(oldu_mattk, $attack_damn)), (cptr.ld1uo(oldu_mattk, $attack_damd)));
    else if (cptr.ld1uo(oldu_mattk, $attack_damd))
        tmp = d(
            ((cptr.ld1so(olduasmon, $permonst_mlevel) + 1) | 0),
            (cptr.ld1uo(oldu_mattk, $attack_damd))
        );
    else
        tmp = 0;

    /* These affect the enemy even if you were "killed" (rehumanized) */
    switch (cptr.ld1uo(oldu_mattk, $attack_adtyp)) {
        case NHM.AD_ACID:
        if (!rn2(2)) {
            pline_mon(
                mtmp,
                __s_s_is_splashed_by_s_s,
                Monnam(mtmp),
                !Upolyd() ? __s_empty : __s_your,
                hliquid(__s_acid)
            );
            if (Resists_Elem(mtmp, NHC.ACID_RES)) {
                pline_mon(mtmp, __s_s_is_not_affected, Monnam(mtmp));
                tmp = 0;
            }
        } else
            tmp = 0;
        if (!rn2(30))
            erode_armor(mtmp, NHM.ERODE_CORRODE);
        if (!rn2(6))
            acid_damage((cptr.ldPtro((mtmp), $monst_mw)));
        return assess_dmg(mtmp, tmp);
        case NHM.AD_STON:
        {
            let protector = attk_protection(cptr.ld1u(mattk));
            let wornitems = cptr.ldI64o(mtmp, $monst_misc_worn_check);

            /* wielded weapon gives same protection as gloves here */
            if ((cptr.ldPtro((mtmp), $monst_mw)) !== null)
                wornitems |= 16n;

            if (!Resists_Elem(mtmp, NHC.STONE_RES) &&
                    (protector == 0n ||
                        (protector != -1n && (wornitems & protector) != protector))) {
                if (poly_when_stoned(cptr.ldPtro(mtmp, $monst_data))) {
                    mon_to_stone(mtmp);
                    return 1;
                }
                pline_mon(mtmp, __s_s_turns_to_stone, Monnam(mtmp));
                cptr.st1o(gs, $instance_globals_s_stoned, 1);
                xkilled(mtmp, NHM.XKILL_NOMSG);
                if (!(cptr.ldI32o((mtmp), $monst_mhp) < 1))
                    return NHM.M_ATTK_HIT;
                return NHM.M_ATTK_AGR_DIED;
            }
            return NHM.M_ATTK_HIT;
        }
        case NHM.AD_ENCH:
        if (mon_currwep) {
            /* by_you==True: passive counterattack to hero's action
               is hero's fault */
            void drain_item(mon_currwep, 1);
            /* No message */
        }
        return NHM.M_ATTK_HIT;
        default:
        break;
    }
    if (!Upolyd())
        return NHM.M_ATTK_HIT;

    /* These affect the enemy only if you are still a monster */
    if (rn2(3))
        switch (cptr.ld1uo(oldu_mattk, $attack_adtyp)) {
            case NHM.AD_PHYS:
            if (cptr.ld1u(oldu_mattk) == NHM.AT_BOOM) {
                You(__s_explode);
                /* KMH, balance patch -- this is okay with unchanging */
                rehumanize();
                return assess_dmg(mtmp, tmp);
            }
            break;
            case NHM.AD_PLYS:
            if (tmp > 127)
                tmp = 127;
            if (cptr.ldI32o(u, $you_umonnum) == NHC.PM_FLOATING_EYE) {
                if (!rn2(4))
                    tmp = 127;
                if ((cptr.ldI32o(mtmp, $monst_mcansee) & 1) | 0 &&
                        ((cptr.ldU64o((cptr.ldPtro(mtmp, $monst_data)), $permonst_mflags1) &
                            4096n) == 0n) &&
                        rn2(3) &&
                        (((cptr.ldU64o((cptr.ldPtro(mtmp, $monst_data)), $permonst_mflags1) &
                            16777216n) != 0n) ||
                            !Invis())) {
                    if (Blind()) {
                        pline(
                            __s_as_a_blind_s_you_cannot_defend_yourself,
                            pmname(
                                cptr.ldPtro(gy, $instance_globals_y_youmonst + $monst_data),
                                cptr.ld1so(flags, $flag_female) ? NHC.FEMALE : NHC.MALE
                            )
                        );
                    } else {
                        if (mon_reflects(mtmp, __s_your_gaze_is_reflected_by_s_s))
                            return 1;
                        pline_mon(mtmp, __s_s_is_frozen_by_your_gaze, Monnam(mtmp));
                        paralyze_monst(mtmp, tmp);
                        return NHM.M_ATTK_AGR_DONE;
                    }
                }
            } else {
                pline_mon(mtmp, __s_s_is_frozen_by_you, Monnam(mtmp));
                paralyze_monst(mtmp, tmp);
                return NHM.M_ATTK_AGR_DONE;
            }
            return NHM.M_ATTK_HIT;
            case NHM.AD_COLD:
            if (Resists_Elem(mtmp, NHC.COLD_RES)) {
                shieldeff(cptr.ldI16o(mtmp, $monst_mx), cptr.ldI16o(mtmp, $monst_my));
                pline_mon(mtmp, __s_s_is_mildly_chilly, Monnam(mtmp));
                golemeffects(mtmp, NHM.AD_COLD, tmp);
                tmp = 0;
                break;
            }
            pline_mon(mtmp, __s_s_is_suddenly_very_cold, Monnam(mtmp));
            cptr.stI32o(
                u,
                $you_mh,
                (cptr.ldI32o(u, $you_mh) + ((((tmp + rn2(2)) | 0) / 2) | 0)) | 0
            );
            if (cptr.ldI32o(u, $you_mhmax) < cptr.ldI32o(u, $you_mh))
                cptr.stI32o(u, $you_mhmax, cptr.ldI32o(u, $you_mh));
            if (cptr.ldI32o(u, $you_mhmax) >
                    (Math.imul(
                        ((cptr.ld1so(
                            cptr.ldPtro(gy, $instance_globals_y_youmonst + $monst_data),
                            $permonst_mlevel
                        ) + 1) | 0),
                        8
                    )))
                void split_mon(cptr.add(gy, $instance_globals_y_youmonst), mtmp);
            break;
            case NHM.AD_STUN:
            if (!(cptr.ldI32o(mtmp, $monst_mstun) & 1)) {
                cptr.stI32o(mtmp, $monst_mstun, 1);
                pline_mon(
                    mtmp,
                    __s_s_s__3,
                    Monnam(mtmp),
                    makeplural(stagger(cptr.ldPtro(mtmp, $monst_data), __s_stagger))
                );
            }
            tmp = 0;
            break;
            case NHM.AD_FIRE:
            if (Resists_Elem(mtmp, NHC.FIRE_RES)) {
                shieldeff(cptr.ldI16o(mtmp, $monst_mx), cptr.ldI16o(mtmp, $monst_my));
                pline_mon(mtmp, __s_s_is_mildly_warm, Monnam(mtmp));
                golemeffects(mtmp, NHM.AD_FIRE, tmp);
                tmp = 0;
                break;
            }
            pline_mon(mtmp, __s_s_is_suddenly_very_hot, Monnam(mtmp));
            break;
            case NHM.AD_ELEC:
            if (Resists_Elem(mtmp, NHC.SHOCK_RES)) {
                shieldeff(cptr.ldI16o(mtmp, $monst_mx), cptr.ldI16o(mtmp, $monst_my));
                pline_mon(mtmp, __s_s_is_slightly_tingled, Monnam(mtmp));
                golemeffects(mtmp, NHM.AD_ELEC, tmp);
                tmp = 0;
                break;
            }
            pline_mon(mtmp, __s_s_is_jolted_with_your_electricity, Monnam(mtmp));
            break;
            default:
            tmp = 0;
            break;
        }
    else
        tmp = 0;

    return assess_dmg(mtmp, tmp);
}

/** C ref: mhitu.c:2616 @returns {CPtr<struct monst>} */
export function cloneu() {
    let mon;
    let mndx = (cptr.ldI32o(
        (cptr.ldPtro(gy, $instance_globals_y_youmonst + $monst_data)),
        $permonst_pmidx
    ));

    if (cptr.ldI32o(u, $you_mh) <= 1)
        return null;
    if (cptr.ld1uo2(
        svm,
        mndx,
        $sizeof_mvitals,
        $instance_globals_saved_m_mvitals + $mvitals_mvflags
    ) &
            NHM.G_EXTINCT)
        return null;
    mon = makemon(
        cptr.ldPtro(gy, $instance_globals_y_youmonst + $monst_data),
        cptr.ldI16(u),
        cptr.ldI16o(u, $you_uy),
        133121
    );
    if (!mon)
        return null;
    cptr.stI32o(mon, $monst_mcloned, 1);
    mon = christen_monst(mon, svp);
    initedog(mon, 1);
    cptr.st1o(
        mon,
        $monst_m_lev,
        uchar(cptr.ld1so(
            cptr.ldPtro(gy, $instance_globals_y_youmonst + $monst_data),
            $permonst_mlevel
        ))
    );
    cptr.stI32o(mon, $monst_mhpmax, cptr.ldI32o(u, $you_mhmax));
    cptr.stI32o(mon, $monst_mhp, (cptr.ldI32o(u, $you_mh) / 2) | 0);
    cptr.stI32o(u, $you_mh, (cptr.ldI32o(u, $you_mh) - cptr.ldI32o(mon, $monst_mhp)) | 0);
    cptr.st1(disp, 1);
    return mon;
}

